def fall(grid):
    """Each non-background cell moves down one if the cell below is background or outside; cells blocked from below stay."""
    bg=Counter(v for r in grid for v in r).most_common(1)[0][0]
    h,w=len(grid),len(grid[0])
    out=[[bg]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=bg:
                if i+1<h: out[i+1][j]=grid[i][j]
                # else: lost
    return out
def fall_blocked(grid):
    """Cell moves down only if the cell below is inside and background; blocked or edge cells stay."""
    bg=Counter(v for r in grid for v in r).most_common(1)[0][0]
    h,w=len(grid),len(grid[0])
    out=[[bg]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=bg:
                if i+1<h and grid[i+1][j]==bg: out[i+1][j]=grid[i][j]
                else: out[i][j]=grid[i][j]
    return out
